"""从教师评价 Markdown 生成自包含 HTML；不改变候选方案的选型状态。"""
from pathlib import Path
from html import escape as esc
import re
ROOT = Path(__file__).resolve().parents[1]
BASE = ROOT / 'docs/演示项目/教师评价/指标方案'
META = {
 'A': ('玉林参考版', '三级 · 5维度 / 21领域 / 43指标', '延续玉林正文五维；二、三级指标为本项目细化建议。', '专业能力20%、教学能力50%、教研能力20%、社会影响10%；师德独立。仅供讨论，未启用。', '日常记录，学期反馈，学年汇总；正式师德与人事考核另按学校适用制度。'),
 'B': ('国家标准转译版', '三级 · 3维度 / 14领域 / 28指标', '依据2012年正式专业标准的3维14领域转译；28项是产品观察项，原标准有63项基本要求。', '默认不设总分。学校需要计分时，先明确岗位量规和权重。', '日常采集，学期反馈，学年发展报告；正式师德结论单独衔接。'),
 'C': ('精简推荐版', '两级 · 4维度 / 12指标', '兼顾日常过程与成果，适合希望低负担记录的学校。', '演示按末级分数直接求和，基础100、上限145、下限25；不额外计权。', '按学期初始化基础分并累计事件；学年保留两学期结果。'),
 'D': ('精细推荐版', '三级 · 6维度 / 20领域 / 60指标', '细分教学、科研、成长、协作与数字素养；为综合设计建议，非经验证的标准量表。', '教育教学40%、教研科研20%、专业成长15%、协作引领10%、数字素养15%；师德独立。仅供讨论，未启用。', '学期诊断，学年汇总；多年课题按里程碑归期。'),
 'E': ('截图成果分类版', '两级 · 2分组 / 12类别', '保留用户截图可见的12个分类；定义、审核与计分理由是本项目补充建议。', '默认仅归档，不预填两组权重。成果积分须另定级别、贡献比例及上限。', '日常归集，按学期或学年筛选；发生日期与荣誉有效期分别保存。'),
}

def read_scheme(file):
 key=file.name[2];rows=[];dim='';extras={};workflows={};aliases={};domain_aliases={};reports={};section='base'
 for line in file.read_text().splitlines():
  if line.startswith('## 汇报字段与计分配置'):section='report'
  elif line.startswith('## 指标释义与加扣分理由'):section='extras'
  elif line.startswith('## 录入来源与审核分工'):section='workflows'
  elif line.startswith('### 同义名称统一记录') or line.startswith('### 指标简称对照'):section='aliases'
  elif line.startswith('### '):dim=line[4:]
  if not line.startswith('|'):continue
  c=[x.strip() for x in line.strip('|').split('|')]
  if section=='report':
   if len(c)==9 and re.fullmatch(r'[A-E]\d\d',c[0]):reports[c[0]]=dict(zip(['report_definition','example','evaluator','report_plus','report_minus','base','upper','lower'],c[1:]))
  elif section=='extras':
   if len(c)==5 and re.fullmatch(r'[A-E]\d\d',c[0]):extras[c[0]]=dict(zip(['definition','mode','plus','minus'],c[1:]))
  elif section=='workflows':
   if len(c)==7 and re.fullmatch(r'[A-E]\d\d',c[0]):workflows[c[0]]=dict(zip(['category','teacher','teacher_audit','leader','leader_audit','routes'],c[1:]))
  elif section=='aliases':
   if len(c)==3 and re.fullmatch(r'[A-E]\d\d',c[0]):aliases[c[0]]='；'.join(filter(None,[aliases.get(c[0],''),c[1]]))
   elif len(c)==3 and c[0]=='二级领域':domain_aliases[c[2]]=c[1]
  elif key=='A' and len(c)==4 and re.match(r'[A-E]\d\d ',c[1]):
   code,name=c[1].split(' ',1);rows.append(dict(id=code,name=name,dimension=dim,domain=c[0],evidence=c[2],review=c[3]))
  elif key in 'BD' and len(c)==5 and re.fullmatch(r'[BD]\d\d',c[2]):
   rows.append(dict(id=c[2],name=c[3],dimension=c[0],domain=c[1],evidence='',review=c[4]))
  elif key in 'CE' and len(c)==5 and re.fullmatch(r'[CE]\d\d',c[1]):
   rows.append(dict(id=c[1],name=c[2],dimension=c[0],domain='',evidence=c[3],review=c[4]))
 assert len(rows)==len(extras)==len(workflows)==len(reports),(key,len(rows),len(extras),len(workflows))
 for r in rows:
  r.update(extras[r['id']]);r.update(workflows[r['id']]);r.update(reports[r['id']]);r['alias']='；'.join(filter(None,[aliases.get(r['id'],''),domain_aliases.get(r['domain'],'')]))
 return key,rows

