JS='''
const sections=[...document.querySelectorAll('.scheme')],links=[...document.querySelectorAll('.scheme-nav a')];let active;
function applyFilters(s){const q=s.querySelector('input').value.trim().toLocaleLowerCase(),dim=s.querySelector('[data-dimension]').value,route=s.querySelector('[data-route]').value;let count=0;const ids=new Set();s.querySelectorAll('tbody tr').forEach(r=>{const show=(!q||(r.textContent+' '+r.dataset.alias).toLocaleLowerCase().includes(q))&&(!dim||r.dataset.dimension===dim)&&(!route||r.dataset.routes.split('；').includes(route));r.hidden=!show;if(show){count++;ids.add(r.id)}});s.querySelectorAll('.leaves li').forEach(li=>li.hidden=!ids.has(li.querySelector('a').hash.slice(1)));s.querySelectorAll('.domain').forEach(d=>d.hidden=![...d.querySelectorAll('li')].some(li=>!li.hidden));s.querySelectorAll('.dimension').forEach(d=>{d.hidden=![...d.querySelectorAll('.domain')].some(g=>!g.hidden);if(!d.hidden&&(q||dim||route))d.querySelector('details').open=true});s.querySelector('.result-count').textContent=`显示 ${count} / ${s.querySelectorAll('tbody tr').length} 项`;s.querySelectorAll('.empty').forEach(e=>e.hidden=count!==0);s.querySelector('.map').hidden=count===0;s.querySelector('.table-wrap').hidden=count===0;}
function setView(s,name){s.dataset.view=name;s.querySelectorAll('.view').forEach(v=>v.classList.toggle('is-selected',v.dataset.view===name));s.querySelectorAll('[data-view-button]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.viewButton===name)));s.querySelector('[data-map-actions]').hidden=name!=='map';s.querySelector('[data-table-actions]').hidden=name!=='table';}
function activate(k){active=sections.find(s=>s.dataset.key===k)||sections[0];sections.forEach(s=>s.classList.toggle('active',s===active));links.forEach(a=>a.setAttribute('aria-current',String(a.hash===`#scheme-${active.dataset.key}`)));setView(active,active.dataset.view||'table');applyFilters(active);}
function clearFilters(s){s.querySelector('input').value='';s.querySelectorAll('select').forEach(x=>x.value='');applyFilters(s)}
function fromHash(){const match=location.hash.match(/^#(?:scheme-|row-|map-|table-)([A-E])/);activate(match?match[1]:'C');const el=document.getElementById(location.hash.slice(1));if(el&&el.tagName==='TR'){if(el.hidden)clearFilters(active);setView(active,'table');el.scrollIntoView({block:'center'});el.focus({preventScroll:true});}else if(location.hash.startsWith('#map-')||location.hash.startsWith('#table-')){setView(active,location.hash.startsWith('#map-')?'map':'table');el?.scrollIntoView({block:'start'});}}
sections.forEach(s=>{s.querySelector('input').addEventListener('input',()=>applyFilters(s));s.querySelectorAll('select').forEach(x=>x.addEventListener('change',()=>applyFilters(s)));s.querySelector('[data-reset]').addEventListener('click',()=>clearFilters(s));s.querySelector('[data-expand]').addEventListener('click',()=>s.querySelectorAll('.dimension details').forEach(d=>d.open=true));s.querySelector('[data-collapse]').addEventListener('click',()=>s.querySelectorAll('.dimension details').forEach(d=>d.open=false));s.querySelector('[data-print]').addEventListener('click',()=>window.print());s.querySelectorAll('[data-view-button]').forEach(b=>b.addEventListener('click',()=>{setView(s,b.dataset.viewButton);history.replaceState(null,'',`#${b.dataset.viewButton}-${s.dataset.key}`)}));s.querySelectorAll('.leaves a').forEach(a=>a.addEventListener('click',()=>setView(s,'table')));s.querySelectorAll('.backlink').forEach(a=>a.addEventListener('click',()=>setView(s,'map')));});
window.addEventListener('hashchange',fromHash);let printDetails=[];window.addEventListener('beforeprint',()=>{printDetails=[...active.querySelectorAll('details')].map(d=>[d,d.open]);printDetails.forEach(([d])=>d.open=true)});window.addEventListener('afterprint',()=>printDetails.forEach(([d,o])=>d.open=o));document.body.classList.add('ready');fromHash();
'''

def generate():
 nav=[];panels=[];total=0
 for f in sorted(BASE.glob('方案?-*.md')):
  k,rows=read_scheme(f);total+=len(rows);title,structure,source,weight,period=META[k];dims=list(dict.fromkeys(r['dimension'] for r in rows))
  nav.append(f'<a href="#scheme-{k}"><strong>{k}</strong>{title}</a>');branches=[]
  for dimension in dims:
   subset=[r for r in rows if r['dimension']==dimension];domains=list(dict.fromkeys(r['domain'] for r in subset));groups=[]
   for domain in domains:
    leaves=''.join(f'<li><a href="#row-{k}-{r["id"]}"><span class="leaf-name">{esc(r["name"])}</span></a></li>' for r in subset if r['domain']==domain)
    groups.append('<div class="domain">'+(f'<div class="domain-title">{esc(domain)}</div>' if domain else '')+f'<ul class="leaves">{leaves}</ul></div>')
   branches.append(f'<div class="dimension"><details open><summary>{esc(dimension)}<small>{len(subset)}项</small></summary><div class="domains">'+''.join(groups)+'</div></details></div>')
  trs=[]
  for r in rows:
   path=' › '.join(x for x in [r['dimension'],r['domain']] if x)
   cells=''.join(f'<td data-label="{label}"'+(' class="score"' if field in ['base','upper','lower'] else '')+f'>{"".join("<div>"+esc(part)+"</div>" for part in r[field].split("；")) if field=="evaluator" else esc(r[field])}</td>' for field,label in [('report_definition','定义'),('example','示例'),('evaluator','评价人'),('report_plus','加分理由'),('report_minus','减分理由'),('base','基础分'),('upper','上限分'),('lower','下限分')])
   trs.append(f'''<tr id="row-{k}-{r['id']}" tabindex="-1" data-dimension="{esc(r['dimension'])}" data-routes="{esc(r['routes'])}" data-alias="{esc(r['alias']+' '+r['category']+' '+r['id'])}"><th scope="row">{esc(r['name'])}<span class="path">{esc(path)}</span></th>{cells}</tr>''')
  options=''.join(f'<option>{esc(d)}</option>' for d in dims)
  if k=='C':
   sums={field:sum(float(r[field]) for r in rows) for field in ['base','upper','lower']}
   context=f'<div class="report-context"><span>基础总分<strong>{sums["base"]:g}</strong></span><span>上限合计<strong>{sums["upper"]:g}</strong></span><span>下限合计<strong>{sums["lower"]:g}</strong></span><span class="scope">按学期计分 · 末级直接求和</span></div>'
  else:context='<p class="report-note">分值待学校配置，表中“—”不代表0分。</p>'
  panels.append(f'''<section class="scheme sheet" id="scheme-{k}" data-key="{k}" aria-labelledby="title-{k}">
<div class="summary"><div><div class="summary-title"><h2 id="title-{k}">{title}</h2><span class="status">{structure}</span></div><p class="source">{source}</p></div></div>{context}
<div class="toolbar js-only"><label class="search-label">查找指标<input type="search" aria-label="搜索方案{k}指标" placeholder="搜索指标、定义或示例"></label><label>一级维度<select data-dimension><option value="">全部维度</option>{options}</select></label><label>录入通道<select data-route><option value="">全部通道</option><option>教师录入·免审</option><option>教师录入·需审核</option><option>管理者录入</option></select></label><button data-reset>重置</button><span class="result-count" role="status" aria-live="polite">共{len(rows)}项</span></div>
<div class="viewbar js-only"><div class="segmented" role="group" aria-label="展示方式"><button data-view-button="map" aria-pressed="false">指标导图</button><button data-view-button="table" aria-pressed="true">指标明细</button></div><div class="view-actions" data-map-actions hidden><button data-expand>全部展开</button><button data-collapse>收起分支</button></div><div class="view-actions" data-table-actions><button class="print-control" data-print>打印当前结果</button></div></div>
<div class="view" data-view="map" id="map-{k}"><p class="empty" hidden>没有符合条件的指标，请更换关键词或重置筛选。</p><div class="map" aria-label="{title}指标树"><div class="root-node">{title}</div><div class="dimensions">{''.join(branches)}</div></div></div>
<div class="view" data-view="table" id="table-{k}"><p class="empty" hidden>没有符合条件的指标，请更换关键词或重置筛选。</p><div class="table-wrap" role="region" aria-label="{title}指标明细"><table class="report-table"><caption class="print-only">{title} · 指标与计分配置</caption><colgroup><col style="width:10%"><col style="width:15%"><col style="width:17%"><col style="width:12%"><col style="width:15%"><col style="width:16%"><col style="width:5%"><col style="width:5%"><col style="width:5%"></colgroup><thead><tr><th scope="col">指标名称</th><th scope="col">定义</th><th scope="col">示例</th><th scope="col">评价人</th><th scope="col">加分理由</th><th scope="col">减分理由</th><th scope="col" class="score">基础分</th><th scope="col" class="score">上限分</th><th scope="col" class="score">下限分</th></tr></thead><tbody>{''.join(trs)}</tbody></table></div></div>
</section>''')
 html='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="教师评价指标体系、评价示例、评价人及基础分与上下限配置。"><title>教师评价指标方案 · 导图与明细</title><style>'''+CSS+'''</style></head><body><a class="skip" href="#schemes">跳到指标方案</a><main><header><div><h1>教师评价指标方案</h1><p>五套候选方案 · 精简版分值为演示配置，待学校确认</p></div></header><nav class="scheme-nav" aria-label="浏览指标方案">'''+''.join(nav)+'''</nav><p class="report-note">指标统一配置评价角色、是否需审核。教师录入本人；管理者查看全校数据与报表、评价他人。提交后按指标配置直接生效或一次审核生效。未配置计分时仅归档。</p><noscript><p>未启用脚本，以下依次展示五套方案。</p></noscript><div id="schemes">'''+''.join(panels)+'''</div><details class="rules"><summary>成果级别与成长时光轴</summary><p>指标评价能力与表现；成果类别说明材料是什么，级别说明认定范围。三者分别保存，级别不增加指标层级。</p><p><strong>科研成果 → 课题研究 · 市级 · 结题</strong>：阶段、本人贡献与认定依据单独记录；按学校规则审核和计分，仍受“科研成果”的基础分与上下限约束。</p><p>级别可配置为校级、区县级、市级、省级、国家级，集团级由学校选用；仅对适用材料启用。日常反思、师德事件不强制填写级别，材料未说明时保留“待确认”。</p><p>成长时光轴按发生日期排列，可按指标、级别、学期筛选；每条展示事件、指标、适用级别、审核状态与生效分值。教师查看本人，管理者查看授权范围。</p></details><details class="rules"><summary>手机端页面与AI流程</summary><p><strong>记录</strong>：教师说事、拍照或上传材料；管理者查看全校记录、评价教师及处理待审。</p><p><strong>档案</strong>：时光轴与按指标查看共用一套档案；按类别、级别及阶段筛选，详情查看材料。管理者可进入全校任一教师档案。</p><p><strong>报表</strong>：教师看本人，管理者看全校；维度、成果类别及级别汇总可查到教师和具体记录。</p><p><strong>我的</strong>：个人资料、学校指标规则及帮助。</p><p>AI识别对象与事实、归并同一事件的多页材料、匹配学校规则；缺项才追问，重复成果不重复计分。按指标审核开关直接生效或一次审核后生效，档案与报表同步。</p></details><footer class="footer"><a href="../教师手机端页面结构方案.md">手机端页面结构</a><a href="../参考资料/教师成长记录竞品体验与方案取舍.md">竞品体验与方案取舍</a><a href="成果级别与成长时光轴设计.md">级别与时光轴完整方案</a><a href="指标字段与事件计分模型.md">计分规则与字段说明</a><a href="README.md">方案依据与原文</a></footer></main><script>'''+JS+'''</script></body></html>'''
 target=BASE/'教师评价指标方案-导图与明细.html';target.write_text(html)
 print(f'已生成：{target.relative_to(ROOT)}（5套方案，{total}项指标，9列汇报明细）')
